// === Tab: sketch54024 ===
// === Translated to P5.js Original by @Gooody: https://openprocessing.org/sketch/386707
// BG Music by <a href="https://pixabay.com/users/fkbeats-40562126/?utm_source=link-attribution&utm_medium=referral&utm_campaign=music&utm_content=251093">Ferhat Kocyigit</a> from <a href="https://pixabay.com/music//?utm_source=link-attribution&utm_medium=referral&utm_campaign=music&utm_content=251093">Pixabay</a>
//electricit sound by <a href="https://pixabay.com/users/freesound_community-46691455/?utm_source=link-attribution&utm_medium=referral&utm_campaign=music&utm_content=6353">freesound_community</a> from <a href="https://pixabay.com/sound-effects//?utm_source=link-attribution&utm_medium=referral&utm_campaign=music&utm_content=6353">Pixabay</a>
const thold      = 5;
let spifac     = 1.05;
let   outnum     = 70;
const drag       = 0.21;
const big        = 500;
let freq=0
let bodies  = [];
let mX = 0, mY = 0;
function preload()
{
	bgMusic=loadSound("https://openprocessing.org/sketch/2719395/files/fk-beats-electroshock-251093.mp3")
	electricity=loadSound("https://openprocessing.org/sketch/2719395/files/electricity-6353.mp3")
}

function setup() {
	bgMusic.loop()
  createCanvas(windowWidth, windowHeight);
  stroke(255, .5);

  background(0);
  for (let i = 0; i < big; i++) {
    bodies.push(new Ball());
  }
	osc = new p5.Oscillator('sine');
  osc.start();

}

function draw() {
	osc.freq(freq);
	osc.amp(.2) 
  let baseFreq = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 1, 800);
  let modulation = map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, 200, 0);
  freq = baseFreq + modulation * sin(frameCount * 0.05);
	pixelDensity(random(.5,1))
	colorMode(HSB,360,100,100)
	stroke(random(360),100,100)
	strokeWeight(random(1))
  mX += 0.9 * ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - mX);
  mY += 0.8 * ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - mY);
  for (let i = 0; i < big; i++) bodies[i].render();
}

class Ball {
  constructor() {
    this.X  = random(width);
    this.Y  = random(height);
    this.w  = random(1 / thold, thold);
    this.Xv = this.Yv = 0;
    this.pX = this.X;
    this.pY = this.Y;
  }

  render() {
    if (!((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {
      this.Xv /= spifac;
      this.Yv /= spifac;
			electricity.stop()
    }
		else
		{
			freq=random(1000)
			if(electricity.isPlaying()==false) electricity.play()
			this.Xv += random(50)+drag * (mX - this.X) * this.w;
    	this.Yv += drag * (mY - this.Y) * this.w;
		}

    this.Xv += drag * (mX - this.X) * this.w;
    this.Yv += drag * (mY - this.Y) * this.w;

    this.X += this.Xv;
    this.Y += this.Yv;

    line(this.X, this.Y, this.pX, this.pY);
		strokeWeight(.3)
		line(this.X, this.Y, this.pX+random(-1000,1000), this.pY+random(-1000,1000));
		circle(this.X, this.Y, this.pX/1000);
		circle(this.X+random(-1000,1000), this.Y+random(-1000,1000), this.pX/1000);
    this.pX = this.X;
    this.pY = this.Y;
  }
}

